x;justify-content:space-between;gap:12px;margin-top:15px;padding-top:12px;border-top:1px dashed #cbd5e1;font-weight:700}.pill{display:inline-flex;padding:6px 10px;border-radius:999px;background:var(--blue-soft);color:var(--blue-dark);font-variant-numeric:tabular-nums}.results{position:sticky;top:16px}.total{text-align:center;padding:10px 0 18px}.total .num{font-size:54px;line-height:1;font-weight:850;color:var(--blue);letter-spacing:-.04em;font-variant-numeric:tabular-nums}.total .label{color:var(--muted);margin-top:5px}.result-row{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-top:1px solid #edf1f5;font-size:14px}.result-row strong{text-align:right;font-variant-numeric:tabular-nums}.priority{margin:14px 0 4px;padding:11px;border-radius:10px;background:#f8fafc;border:1px solid var(--border);text-align:center;font-weight:700;color:var(--muted)}.priority.yes{background:var(--green-soft);border-color:#b7e0c7;color:var(--green)}.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px}button{border:0;border-radius:10px;padding:11px;font-weight:700;cursor:pointer;font-size:14px;background:var(--blue);color:#fff}button.secondary{background:#e7ecf2;color:#243244}.source{background:#fff;border:1px solid var(--border);border-radius:14px;padding:16px;margin-top:18px;color:var(--muted);font-size:13.5px}.source strong{color:var(--text)}.credits{text-align:center;margin-top:20px;color:#7a8490;font-size:13px}.hidden{display:none!important}@media(max-width:900px){.layout{grid-template-columns:1fr}.results{position:static}}@media(max-width:650px){body{padding:16px 10px}.hero{padding:24px 19px}.field-grid{grid-template-columns:1fr}.card{padding:16px}.actions{grid-template-columns:1fr}}
